import{_ as p,a0 as a,w as n,s as l,ao as s,I as o,x as i,a1 as t,A as f}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"LibreOffice 簡史 | LCTT x X-CMD","titleTemplate":false,"description":"LibreOffice 簡史 | LCTT (202302) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LibreOffice 簡史 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LibreOffice 簡史 | LCTT (202302) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202302/20230207.1 ⭐️⭐️ A brief history of LibreOffice","title":"LibreOffice 簡史","tag":"202302","desc":""},"relativePath":"202302/20230207.1 ⭐️⭐️ A brief history of LibreOffice.md","filePath":"[post].md"}'),O={name:"202302/20230207.1 ⭐️⭐️ A brief history of LibreOffice.md"};function b(u,e,c,d,m,g){const r=a("Link");return n(),l("div",null,[e[15]||(e[15]=s('<h1 id="libreoffice-簡史" tabindex="-1">LibreOffice 簡史 <a class="header-anchor" href="#libreoffice-簡史" aria-label="Permalink to “LibreOffice 簡史”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202302/20/191328egg1odg1gegdgd91.jpg" alt=""></p><blockquote><p>LibreOffice 的起源故事，它是一個開源的辦公解決方案，確保你總是能夠訪問你的數據並控制你的創造力。</p></blockquote><p>在 2009 年初，OpenOffice.org（OOo）還是微軟 Office 在個人辦公生產力套件市場的主要競爭對手。這個流行的開源辦公套件的社區，期待着 11 月在意大利奧爾維耶託舉行的研討會。事情進展順利，未來看起來很光明。</p><p>可這之後，同年 4 月，<ruby>甲骨文公司<rt>Oracle</rt></ruby> 宣佈了對 <ruby>太陽計算機系統公司<rt>Sun Microsystems</rt></ruby> 的收購計劃。</p><p>就個人而言，我覺得這對 OpenOffice.org 來説是個壞消息。甲骨文對開源套件沒有興趣，我料想它會放棄這個項目。當然，我更希望在研討會上被證明是我想錯了。但到最後，甲骨文只派了一名代表來到奧爾維耶託，乏善可陳，含糊其辭地談論了貨幣化和品牌重塑。我和其他社區成員們都覺得，最擔心的事情成真了。</p><p>那一年，社區成員從奧爾維耶託返程之後決定採取行動。是時候兑現 OpenOffice.org 項目的承諾了。我們決心創建一個獨立的基金會來管理項目的資產，在社區的保護下促進套件的開發。OpenOffice.org 將不再隸屬於哪一家公司，而是屬於它的用户和個人貢獻者們。</p><h3 id="建立基金會" tabindex="-1">建立基金會 <a class="header-anchor" href="#建立基金會" aria-label="Permalink to “建立基金會”">​</a></h3><p>當時，OpenOffice.org 項目分佈在世界各地，在語言社區幫助下進行本地化和推廣，其中最主要的四個是：</p><ul><li>德國：該軟件誕生於德國，而且 Star Division（負責 OpenOffice.org 的部門）的總部也在漢堡，因此開發者羣體和德語支持者之間溝通順暢。</li><li>法國：政府支持這個開源軟件。</li><li>意大利：我所在的小組。</li><li>巴西。</li></ul><p>2010 年初，在法國和德國語言社區的倡議下，最活躍的志願者 —— 連同一些獨立開發者和 SUSE 的開發者們 —— 着手建立了一個復刻項目，旨在作為一個額外的選擇，讓全球社區和投資 OpenOffice.org 的企業能夠同時參與進來。</p><p>我在國際商業諮詢機構已有超過 30 年的工作經驗了。在這個項目中負責市場營銷和戰略溝通。</p><p>隨後的幾個月裏，活動越發忙碌。由於從 Star Division 傳來的消息越來越負面，每週都得召開一次電話會議。</p><p>即使 OpenOffice.org 的解散似乎迫在眉睫，我們還是通過發佈文章徵稿（CFP）的方式，確認了位於布達佩斯的研討會仍將舉辦。當然，復刻項目的成員在做的也和往年別無二致。他們提交了演講提案並制定了旅行計劃。</p><h3 id="一個安全的文件存放處" tabindex="-1">一個安全的文件存放處 <a class="header-anchor" href="#一個安全的文件存放處" aria-label="Permalink to “一個安全的文件存放處”">​</a></h3><p>夏初，復刻項目幾乎要完成了。我們的小組在布達佩斯開會評估 OpenOffice.org 方面的境況，並召開了第一次面對面的組織會議。</p><p>布達佩斯的研討會進行得很順利，為期三天日程中舉行了會議、主題演講和技術研討。一切似乎還算平常。</p><p>可其實並不平常。</p><p>當幾位領頭人沒去參加會議的主要社交活動 —— 多瑙河上過夜巡遊的時候，一些與會者開始有些疑慮了。其實我們沒參加這次活動，是因為我們在餐廳開會敲定新基金會的最終細節，有太多事情要確保萬無一失。我們必須定下公告日期，並且，為了協調基金會落地的各項任務，需要確定指導委員會的人員組成。</p><h3 id="libreoffice" tabindex="-1">LibreOffice <a class="header-anchor" href="#libreoffice" aria-label="Permalink to “LibreOffice”">​</a></h3><p>從這次會議到 LibreOffice 發佈間隔了三週，我們緊鑼密鼓地準備。我擬好了發佈策略和新聞稿，開發者們為軟件做準備。應用的名字甚至是在發佈的前幾天的一次電話會議上敲定的，那時我在格羅塞託，正在參加意大利開源軟件社區會議。</p><p>2010 年 9 月 28 日，我把宣佈“<ruby>文檔基金會<rt>The Document Foundation</rt></ruby>”和 LibreOffice 的新聞稿分發到一個包含約 250 名記者的全球郵件列表中，這列表可是我根據供職過的公共關係機構的來信，花了很大力氣整理的。</p><p>新聞稿是這樣的：</p><blockquote><p>開發和推廣 OpenOffice.org 的志願者社區宣佈將成立一個獨立的基金會，推動項目的進一步發展。基金會將成為一個新的生態系統的基石，在這裏，個人和組織都可以為一個真正免費的辦公套件做出貢獻，並從中受益。從用户的利益出發，這將帶來更多的競爭和選擇，並推動辦公套件市場的創新。從現在開始，OpenOffice.org 社區將被稱為“<ruby>文檔基金會<rt>The Document Foundation</rt></ruby>”。</p></blockquote><p>我們邀請過 Oracle 成為基金會的成員，並捐贈社區在過去十年中發展起來的品牌。而在他們做出決定之前，我們選擇了 LibreOffice 作為即將到來的軟件的品牌。</p><p>媒體界對這一公告的反應非常積極。但另一方面，企業和分析師則傾向於對由社區管理的辦公套件表示質疑，這是他們從未完全理解的實體，因為這個組織很扁平、任人唯賢。</p><p>公告發布後的兩週內，就有 80 位新開發者加入這個項目，推翻了那些認為“僅憑 SUSE 和 Red Hat 的開發者來啓動復刻項目並不現實”的預測。不出所料，大多數語言社區都轉向了 LibreOffice。</p><p>LibreOffice 是基於 OpenOffice.org 的源代碼構建的。但新的功能被集成在 <ruby>Go-OO<rt>Go-Open Office</rt></ruby> 的源代碼中，而不是在 OpenOffice.org（OOo）上。</p><p>出於這個原因，LibreOffice 的第一個版本（於 2011 年 1 月 25 日發佈）為 3.3，以保持與 OpenOffice.org 的一致性。我們認為這對於從第一個版本遷移到新套件的用户很有幫助。由於還有必須解決的明顯技術債務，該軟件仍有點不成熟，這導致了一些問題和不穩定。這些問題預計將基本上通過 3.x 和 4.x 版本的代碼清理和重構得到糾正。到了 5.x 和 6.x 版本，源代碼應該已經穩定，並有條件改進用户界面，以及開發移動和雲版本。</p><p>2011 年春天，甲骨文將 OpenOffice.org 源代碼轉讓給了 Apache 軟件基金會。但該項目僅持續了三年，它的上一個新版本已經是將近十年前的事了。</p><h3 id="未來是開放的" tabindex="-1">未來是開放的 <a class="header-anchor" href="#未來是開放的" aria-label="Permalink to “未來是開放的”">​</a></h3><p>文檔基金會的組建過程於 2012 年初結束，並於 2012 年 2 月 17 日在柏林有關部門完成註冊。因為創始人希望該項目的志願者成員們也可以根據貢獻成為基金會成員，這讓註冊過程十分漫長。德國的法規並未考慮到基金會的這一細節，因此需要對章程進行多次修訂才能滿足現有狀況。</p><p>基金會成立之初的前兩項活動都是委員會成員的選舉。這是從單純的志願者過渡到基於貢獻的文檔基金會成員所必經的規程。有委員五人，副委員三人。最後，負責在行政和戰略方面領導基金會的董事會，由七名成員和三名副手組成。</p><p>2012 年底，基金會聘請了第一位僱員 Florian Effenberger，在後來他被提升為執行董事。今天，這個團隊有十幾個成員，他們負責日常活動，例如協調項目、行政管理、網絡基礎設施管理、軟件發佈、指導新的開發人員、協調質量保證、用户界面的演進、以及營銷和溝通。</p><p>目前，基金會正在尋找開發人員滿足企業客户需求，例如 RTL 語言管理和輔助功能。這些功能並不是由 LibreOffice 生態系統中的公司開發的，這些公司為他們提供功能開發服務、三級支持以及為企業需求優化的軟件的長期支持版本。</p><p>在 LibreOffice 和文檔基金會宣佈成立已經過去 12 年之後，我們可以説，我們已經實現了開發一個獨立的“<ruby>自由和開源軟件<rt>free and open source</rt></ruby>（FOSS）”的項目目標。我們的項目是基於一個由個人志願者和公司量力而行做出貢獻的擴展社區。參與者們幫助創建了無與倫比的免費辦公套件，並通過採用和發展現有市場上唯一真正的<ruby>標準辦公文檔格式<rt>Open Document Format</rt></ruby>（ODF）來支持開放標準。同時，該套件也確保了與專有的 OOXML 格式的出色兼容性。</p><p>這種模式的可持續性是一個日常問題。身處於與大型科技公司的激烈競爭下，我們一直在嘗試，試圖在“希望一切都免費”，和“希望每個用户都能力所能及做出貢獻”之間達成一種平衡。不過無論如何，LibreOffice 都會是開源的辦公套件，這提供了競爭之上的額外價值。</p><p>試試 LibreOffice 吧；捐贈；不論是工作還是業餘，支持它；向你的朋友介紹它！LibreOffice 是一個開源的辦公解決方案，它確保你總是能夠訪問你的數據，並掌控你的創造力。</p><hr>',39)),o("p",null,[e[1]||(e[1]=i("via: ",-1)),t(r,{href:"https://opensource.com/article/23/2/libreoffice-history"},{default:f(()=>[...e[0]||(e[0]=[i("https://opensource.com/article/23/2/libreoffice-history",-1)])]),_:1})]),o("p",null,[e[6]||(e[6]=i("作者：",-1)),t(r,{href:"https://opensource.com/users/italovignoli"},{default:f(()=>[...e[2]||(e[2]=[i("Italo Vignoli",-1)])]),_:1}),e[7]||(e[7]=i(" 選題：",-1)),t(r,{href:"https://github.com/lkxed/"},{default:f(()=>[...e[3]||(e[3]=[i("lkxed",-1)])]),_:1}),e[8]||(e[8]=i(" 譯者：",-1)),t(r,{href:"https://github.com/onionstalgia"},{default:f(()=>[...e[4]||(e[4]=[i("onionstalgia",-1)])]),_:1}),e[9]||(e[9]=i(" 校對：",-1)),t(r,{href:"https://github.com/wxy"},{default:f(()=>[...e[5]||(e[5]=[i("wxy",-1)])]),_:1})]),o("p",null,[e[12]||(e[12]=i("本文由 ",-1)),t(r,{href:"https://github.com/LCTT/TranslateProject"},{default:f(()=>[...e[10]||(e[10]=[i("LCTT",-1)])]),_:1}),e[13]||(e[13]=i(" 原創編譯，",-1)),t(r,{href:"https://linux.cn/"},{default:f(()=>[...e[11]||(e[11]=[i("Linux中國",-1)])]),_:1}),e[14]||(e[14]=i(" 榮譽推出",-1))])])}const x=p(O,[["render",b]]);export{T as __pageData,x as default};
